protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs,
                          boolean currentAltReachedAcceptState, boolean speculative) {
    if (debug) {
        System.out.println("closure(" + config.toString(recog, true) + ")");
    }

    if (config.state instanceof RuleStopState) {
        handleRuleStopState(input, config, configs, currentAltReachedAcceptState);
    } else {
        processNonRuleStopState(config, configs, currentAltReachedAcceptState);
    }

    return currentAltReachedAcceptState;
}

private void handleRuleStopState(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs,
                                  boolean currentAltReachedAcceptState) {
    if (debug) {
        logRuleStopState(config);
    }

    if (isEmptyContext(config)) {
        configs.add(config);
    } else {
        processContext(config, configs);
        currentAltReachedAcceptState = true;
    }
}

private void logRuleStopState(LexerATNConfig config) {
    if (recog != null) {
        System.out.format("closure at %s rule stop %s\
", recog.getRuleNames()[config.state.ruleIndex], config);
    } else {
        System.out.format("closure at rule stop %s\
", config);
    }
}

private boolean isEmptyContext(LexerATNConfig config) {
    return config.context == null || config.context.hasEmptyPath() || config.context.isEmpty();
}

private void processContext(LexerATNConfig config, ATNConfigSet configs) {
    for (SingletonPredictionContext ctx : config.context) {
        if (!ctx.isEmpty()) {
            PredictionContext newContext = ctx.parent; // "pop" return state
            handleReturnState(config, configs, ctx, newContext);
        }
    }
}

private void handleReturnState(LexerATNConfig config, ATNConfigSet configs, SingletonPredictionContext ctx,
                                PredictionContext newContext) {
    if (ctx.returnState == PredictionContext.EMPTY_RETURN_STATE) {
        configs.add(new LexerATNConfig(config, config.state, ctx));
    } else {
        ATNState returnState = atn.states.get(ctx.returnState);
        LexerATNConfig newConfig = new LexerATNConfig(returnState, config.alt, newContext);
        closure(input, newConfig, configs, currentAltReachedAcceptState, speculative);
    }
}

private void processNonRuleStopState(LexerATNConfig config, ATNConfigSet configs, boolean currentAltReachedAcceptState) {
    if (!config.state.onlyHasEpsilonTransitions()) {
        if (!currentAltReachedAcceptState || !config.hasPassedThroughNonGreedyDecision()) {
            configs.add(config);
        }
    }

    ATNState state = config.state;
    for (int i = 0; i < state.getNumberOfTransitions(); i++) {
        Transition transition = state.transition(i);
        LexerATNConfig targetConfig = getEpsilonTarget(input, config, transition, configs, speculative);
        if (targetConfig != null) {
            currentAltReachedAcceptState = closure(input, targetConfig, configs, currentAltReachedAcceptState, speculative);
        }
    }
}

