public String asString() {
    if (start == null) return null;
    marked = new HashSet<ATNState>();

    work = new ArrayList<ATNState>();
    work.add(start);

    StringBuilder buf = new StringBuilder();
    ATNState s;

    while (!work.isEmpty()) {
        s = work.remove(0);
        if (marked.contains(s)) continue;
        int n = s.getNumberOfTransitions();
        marked.add(s);
        buf.append(getStateString(s));

        for (int i = 0; i < n; i++) {
            Transition t = s.transition(i);
            if (!(s instanceof RuleStopState)) { // don\'t add follow states to work
                if (t instanceof RuleTransition) {
                    work.add(((RuleTransition) t).followState);
                } else {
                    work.add(t.target);
                }
            }

            if (t instanceof EpsilonTransition) {
                buf.append("->").append(getStateString(t.target)).append(\'\
\');
            } else if (t instanceof RuleTransition) {
                buf.append("-").append(g.getRule(((RuleTransition) t).ruleIndex).name)
                   .append("->").append(getStateString(t.target)).append(\'\
\');
            } else if (t instanceof ActionTransition) {
                ActionTransition a = (ActionTransition) t;
                buf.append("-").append(a.toString())
                   .append("->").append(getStateString(t.target)).append(\'\
\');
            } else if (t instanceof SetTransition) {
                SetTransition st = (SetTransition) t;
                boolean not = st instanceof NotSetTransition;
                if (g.isLexer()) {
                    buf.append("-").append(not ? "~" : "").append(st.toString())
                       .append("->").append(getStateString(t.target)).append(\'\
\');
                } else {
                    buf.append("-").append(not ? "~" : "").append(st.label().toString(g.getTokenNames()))
                       .append("->").append(getStateString(t.target)).append(\'\
\');
                }
            } else if (t instanceof AtomTransition) {
                AtomTransition a = (AtomTransition) t;
                String label = g.getTokenDisplayName(a.label);
                buf.append("-").append(label)
                   .append("->").append(getStateString(t.target)).append(\'\
\');
            } else {
                buf.append("-").append(t.toString())
                   .append("->").append(getStateString(t.target)).append(\'\
\');
            }
        }
    }
    return buf.toString();
}

public String asString() {
    if (start == null) {
        return null;
    }

    marked = new HashSet<>();
    work = new ArrayList<>();
    work.add(start);

    StringBuilder buf = new StringBuilder();

    while (!work.isEmpty()) {
        ATNState s = work.remove(0);
        if (marked.contains(s)) {
            continue;
        }

        marked.add(s);
        int n = s.getNumberOfTransitions();

        for (int i = 0; i < n; i++) {
            Transition t = s.transition(i);
            processTransition(t, s, buf, work);
        }
    }

    return buf.toString();
