protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, boolean speculative) {
    if (debug) {
        System.out.println("closure(" + config.toString(recog, true) + ")");
    }

    if (config.state instanceof RuleStopState) {
        logRuleStopState(config);

        if (isContextEmptyOrNull(config.context)) {
            handleEmptyOrNullContext(config, configs);
            return true;
        }

        if (config.context != null && !config.context.isEmpty()) {
            processNonEmptyContext(config, input, configs, speculative);
        }

        return currentAltReachedAcceptState;
    }

    if (!config.state.onlyHasEpsilonTransitions() && (!currentAltReachedAcceptState || !config.hasPassedThroughNonGreedyDecision())) {
        configs.add(config);
    }

    return processTransitions(input, config, configs, currentAltReachedAcceptState, speculative);
}

